function generateUuid() {
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(
    /[xy]/g,
    function (character) {
      const random = Math.random() * 16 | 0;
      const value =
        character === 'x'
          ? random
          : (random & 0x3) | 0x8;

      return value.toString(16);
    }
  );
}

const body = $json.body ?? {};
const headers = $json.headers ?? {};

const candidateId = String(
  body.candidate_id ?? ''
).trim();

const domain = String(
  body.domain ?? ''
).trim();

const countries = Array.isArray(body.countries)
  ? body.countries
      .slice(0, 10)
      .map(country => String(country).trim())
      .filter(Boolean)
  : [];

const requestedLimit = Number(body.limit ?? 25);

const limit = Math.min(
  Math.max(Number.isFinite(requestedLimit) ? requestedLimit : 25, 1),
  50
);

if (!/^[0-9a-f-]{36}$/i.test(candidateId)) {
  throw new Error('CANDIDATE_ID_INVALID');
}

if (domain.length < 3 || domain.length > 160) {
  throw new Error('DOMAIN_INVALID');
}

const ownerId = String(
  headers['x-owner-id'] ||
  $env.OUTREACH_DEFAULT_OWNER_ID ||
  ''
).trim();

if (!/^[0-9a-f-]{36}$/i.test(ownerId)) {
  throw new Error('OWNER_ID_INVALID');
}

return [
  {
    json: {
      campaign_id: generateUuid(),
      candidate_id: candidateId,
      owner_id: ownerId,
      domain,
      countries,
      limit
    }
  }
];

