const campaignId =
  $('CONFIGURE - Authorize and Create Campaign').item.json.campaign_id;

const list = $json.professors;

if (!Array.isArray(list)) {
  throw new Error('DISCOVERY_RESPONSE_INVALID');
}

const seen = new Set();
const out = [];

for (const professor of list) {
  const name = String(professor.name ?? '').trim();
  const university = String(professor.university ?? '').trim();

  if (!name || !university) {
    continue;
  }

  const emailValue =
    professor.email === null ||
    professor.email === undefined
      ? null
      : String(professor.email).trim().toLowerCase();

  const email =
    emailValue &&
    /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(emailValue)
      ? emailValue
      : null;

  const profileUrl =
    professor.profile_url &&
    /^https:\/\//i.test(String(professor.profile_url))
      ? String(professor.profile_url).trim()
      : null;

  const sourceUrls = Array.isArray(professor.source_urls)
    ? professor.source_urls
        .map(url => String(url).trim())
        .filter(url => /^https:\/\//i.test(url))
    : [];

  const researchInterest = String(
    professor.research_interest ?? ''
  ).trim();

  const dedupeKey = profileUrl
    ? profileUrl.toLowerCase()
    : `${name.toLowerCase()}|${university.toLowerCase()}`;

  if (seen.has(dedupeKey)) {
    continue;
  }

  seen.add(dedupeKey);

  out.push({
    json: {
      campaign_id: campaignId,
      professor_name: name,
      professor_email: email,
      university,
      canonical_profile_url: profileUrl,
      research_interest: researchInterest,
      evidence_json: JSON.stringify({
        source_urls: sourceUrls,
        verification_status: 'UNVERIFIED'
      }),
      status: 'NEEDS_VERIFICATION'
    },
    pairedItem: {
      item: 0
    }
  });
}

if (!out.length) {
  throw new Error('DISCOVERY_NO_VALID_RESULTS');
}

return out;

const rawText =
  $json.candidates?.[0]?.content?.parts?.[0]?.text;

if (!rawText) {
  throw new Error('GEMINI_EMPTY_RESPONSE');
}

let cleaned = String(rawText).trim();

cleaned = cleaned
  .replace(/^```json\s*/i, '')
  .replace(/^```\s*/i, '')
  .replace(/\s*```$/i, '')
  .trim();

let parsed;

try {
  parsed = JSON.parse(cleaned);
} catch {
  throw new Error('GEMINI_INVALID_JSON');
}

if (!Array.isArray(parsed.professors)) {
  throw new Error('GEMINI_PROFESSORS_ARRAY_MISSING');
}

return [
  {
    json: {
      professors: parsed.professors
    }
  }
];
